insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_144'
from (values
('127.889.d.9.A',3,'A mechanic replaces an engine''s fuel-flow transmitter, checks it for leaks and bolts it back onto the fuel line. She is:','["removing, inspecting and installing a fuel-flow transmitter", "ignoring a transmitter", "buying a transmitter", "painting a transmitter"]'::jsonb,0,'Flow transmitter.','original'),
('127.889.d.9.A',4,'After installing a fuel-flow transmitter, the mechanic should check the fittings for:','["tire wear", "fuel leaks", "seat fit", "paint color"]'::jsonb,1,'Leak check.','original'),
('127.889.d.9.B',3,'A technician swaps the cockpit fuel-flow gauge and tests that it reads zero with the engine off and a normal value when running. She is:','["painting the gauge", "ignoring the gauge", "removing, inspecting and installing a fuel-flow gauge", "skipping the test"]'::jsonb,2,'Flow gauge.','original'),
('127.889.d.9.B',4,'A fuel-flow gauge that reads high at idle may have a problem with the:','["seat belts", "paint", "tires", "transmitter or its wiring"]'::jsonb,3,'Gauge fault.','original'),
('127.889.d.9.C',3,'A student labels the tach generator, wiring and indicator of an electric tachometer. She is:','["identifying components of an electric tachometer system", "labeling lights", "labeling tires", "labeling seats"]'::jsonb,0,'Tach parts.','original'),
('127.889.d.9.C',4,'An electric tachometer system''s sensor is driven by the:','["cabin fan", "engine, producing a signal proportional to rpm", "landing gear", "fuel pump only"]'::jsonb,1,'Tach drive.','original'),
('127.889.d.9.D',3,'A mechanic compares a tachometer''s green and red markings to the engine''s rpm limits listed in the manual. She is:','["painting markings", "ignoring markings", "inspecting tachometer markings for accuracy", "guessing limits"]'::jsonb,2,'Tach marks.','original'),
